 #   Rc::decrement_strong_count(ptr);
 }
 ```"}

{"path": "rust/library/alloc/src/rc.rs", "line": 1361, "name": "decrement_strong_count", "declaration": "unsafe fn decrement_strong_count (ptr : * const T)", "parent": "Rc < T >", "documentation": " Decrements the strong reference count on the `Rc<T>` associated with the
