 let five = Rc::new(5);

 unsafe {
     let ptr = Rc::into_raw(five);
     Rc::increment_strong_count(ptr);

     let five = Rc::from_raw(ptr);
     assert_eq!(2, Rc::strong_count(&five));
     Rc::decrement_strong_count(ptr);
     assert_eq!(1, Rc::strong_count(&five));
 }
 ```"}

